def _cases(kind, rng, count, offset=0):
    cases = []
    for i in range(count):
        key = "c_" + hashlib.sha256(str(rng.getrandbits(128)).encode()).hexdigest()[:16]
        n = rng.randint(2, 9)
        if kind == "exact_type":
            values = [n, -n, 0, True, False, str(n), float(n), None, [], {}]
            case = {"value": values[(i + offset) % len(values)]}
        elif kind == "stale_input":
            original = {k: digest([key, k]) for k in ("task", "state", "digest", "artifact")}
            current = dict(original)
            mode = (i + offset) % 7
            if mode in (1, 2, 3, 4):
                current[list(original)[mode - 1]] = digest([key, "changed"])
            elif mode == 5:
                del current["artifact"]
            elif mode == 6:
                current["state"] = True
            case = {"bound": original, "current": current}
        elif kind == "flow":
            case = {
                "case_id": key,
                "n": 4,
                "s": 0,
                "t": 3,
                "arcs": [
                    [0, 1, n],
                    [0, 2, n + 1],
                    [1, 2, rng.randint(0, 4)],
                    [1, 3, n - 1],
                    [2, 3, n + 2],
