                "case_id": key,
                "A": [[n, 1], [0, rng.randint(1, 5)]],
                "b": [rng.randint(-9, 9), rng.randint(-9, 9)],
            }
            if (i + offset) % 3 == 1:
                case["A"] = [[n, 1], [2 * n, 2]]
            if (i + offset) % 3 == 2:
                case["A"] = [[n, 1], [2 * n, 2]]
                case["b"][1] = 2 * case["b"][0]
        elif kind.startswith("workflow"):
            case = {
                "values": [rng.randint(-20, 20) for _ in range((i + offset) % 5)],
                "factor": n,
                "offset": -n + 1,
            }
            if (i + offset) % 5 == 4:
                case["values"].append(True)
        else:
            op = ["eq3", "distinct", "not_distinct", "is_null", "is_not_null", "and", "or", "not"][
                offset % 8
            ]
            where = {op: [{"col": "v"}, {"col": "w"}]}
            if op in ("is_null", "is_not_null"):
                where = {op: {"col": "v"}}
            elif op == "not":
                where = {"not": {"is_null": {"col": "w"}}}
            elif op in ("and", "or"):
                where = {op: [{"is_null": {"col": "v"}}, {"eq3": [{"col": "w"}, {"val": n}]}]}
            case = {
                "case_id": key,
                "schema": {"records": {"id": "INTEGER", "v": "INTEGER", "w": "INTEGER"}},
                "spec": {"op": "select", "from": "records", "where": where, "project": ["id", "v"]},
                "protected": ["v", "w"],
                "test_databases": [],
            }
            for _ in range(3):
                case["test_databases"].append(
                    {
                        "records": [
                            {
                                "id": j + 1,
                                "v": rng.choice([None, 0, n, -n]),
                                "w": rng.choice([None, 0, n, -n]),
                            }
                            for j in range(rng.randint(0, 8))
                        ]
                    }
                )
        cases.append(case)
    return cases


def freeze_tasks(seed=26457):
    rng = random.Random(seed)
    tasks = []
    kinds = {
        "repair": ["exact_type", "stale_input"],
        "certificate": ["flow", "linear"],
        "workflow": ["workflow_sum", "workflow_prefix"],
    }
    for panel, number in (
        ("selection", 2),
        ("confirmation", 2),
        ("transfer", 4),
        ("ablations", 4),
        ("ignition", 2),
    ):
        for family, members in kinds.items():
            for i in range(number):
                kind = members[i % 2]
                tasks.append(
