                r";|--|/\*|\b(attach|pragma|with|load_extension|randomblob|join|union)\b", sql, re.I
            ):
                return False, "SQL_SURFACE_REFUSED"
        first, second = sql_exact(case, result), sql_independent(case, result)
    else:
        if kind == "exact_type":
            expected = {"accepted": type(case["value"]) is int}
        elif kind == "stale_input":
            a, b = case["bound"], case["current"]
            expected = {
                "accepted": all(
                    type(a.get(k)) is str and bool(a[k]) and type(b.get(k)) is str and a[k] == b[k]
                    for k in ("task", "state", "digest", "artifact")
                )
            }
        elif any(type(v) is not int for v in case["values"]):
            expected = {"error": "TYPE"}
        elif kind == "workflow_sum":
            expected = {"result": sum(case["factor"] * v + case["offset"] for v in case["values"])}
        else:
            expected = {
                "result": [sum(case["values"][: i + 1]) for i in range(len(case["values"]))]
            }
        # Byte-canonical comparison keeps bool distinct from 0/1.
        return canonical(result) == canonical(expected), "EXACT_OPERATION_CHECK"
    return first[0] and second[0], "DUAL_ACCEPT" if first[0] and second[0] else "DUAL_REJECT"


PROGRAM_ENTRYPOINT = """import io,json,runpy,sys
sys.stdin=io.StringIO(json.dumps(json.load(open('input.json'))))
runpy.run_path('solution.py',run_name='__main__')
"""


def execute_cases(runner, code, task, cases, store):
    observed = []
    for case in cases:
        inputs = {k: v for k, v in case.items() if k != "test_databases"}
        execution = runner.execute(
            {"entrypoint.py": PROGRAM_ENTRYPOINT, "solution.py": code}, inputs
        )
        passed = False
        if execution["returncode"] == 0 and not execution["timeout"] and not execution["truncated"]:
            try:
                passed, _ = judge(task["kind"], case, json.loads(execution["stdout"]))
            except (ValueError, TypeError, KeyError, IndexError):
                passed = False
        observed.append(
            {"case": store.put(canonical(case)), "execution": execution, "passed": passed}
        )
    return observed

