            repetition,
            self.store.put(code.encode()),
            bool(best and best["score"] == 1),
            private_pass,
            terminal,
            cost,
            tuple(evidence),
        )
        self.store.record(name + "/evaluation", row.to_dict())
        if fatal:
            raise fatal
        return row


class HarnessProposer:
    def __init__(self, provider, store, *, outer=None, runner=None):
        self.provider, self.store, self.outer, self.runner = provider, store, outer, runner

    def propose(self, incumbent, *, occurrence, evidence, phase):
        root = incumbent
        while root.parent != root.source:
            root = self.store.load(root.parent)
        # Keep at most two prior decisions from this trajectory. Other trajectories
        # and transfer results never become outer-loop optimization context.
        trajectory = occurrence.split("/step-", 1)[0] + "/"
        recent = [
            e["object"]
            for e in self.store.events()
            if e["name"].startswith(trajectory) and e["name"].endswith(("/decision", "/rejected"))
        ][-2:]
        by_task = {}
        for row in evidence:
            by_task.setdefault(row.task, []).append(row)
        request = {
            "role": "outer_rewrite",
            "root": root.candidate_id,
            "champion": incumbent.candidate_id,
            "recent_attempts": recent,
            "parent": incumbent.candidate_id,
            "files": dict(incumbent.files),
            "feedback": [
                {
                    "task": task,
                    "private_passes": sum(r.private_pass for r in rows),
                    "public_passes": sum(r.public_pass for r in rows),
                    "assigned": len(rows),
                    "evidence": rows[-1].receipt_id,
                }
                for task, rows in sorted(by_task.items())[:6]
            ],
        }
        system = (
            "Return only JSON with diagnosis, strategy, mutation and files. Files must contain exactly prompt.txt, "
            "workflow.json, search_policy.py and context_policy.py as complete strings. Edit the current harness. "
            "Keep choose(state) and context(state,choice) interfaces, evidence_refs, root/champion/recent evidence "
            "and the four Boolean workflow options. Diagnose the concrete issue before repair. Never edit host "
            "checkers, tasks, splits, transport, budget, credentials or admission. No external dependencies."
        )
        if self.outer is not None:
            # The evolved outer policy selects and compresses the rewrite context;
            # the fixed host rewrite contract and allowed paths remain mandatory.
            files = dict(self.outer.files)
            state = {
                "seed": int(digest(occurrence)[:8], 16),
                "root": incumbent.candidate_id,
                "attempts": [],
                "task": request,
                "options": json.loads(files["workflow.json"]),
                "memory": [],
            }
            policy = self.runner.execute({**files, "entrypoint.py": POLICY_ENTRYPOINT}, state)
            self.store.record(occurrence + "/outer-policy", {"state": state, "execution": policy})
            if policy["returncode"] or policy["timeout"] or policy["truncated"]:
                raise ValueError("OUTER_POLICY_FAILED")
            request = loads_strict_json(policy["stdout"])["user"]
        call = self.provider.call(
            system,
            json.dumps(request, separators=(",", ":")),
            role="outer",
            phase=phase,
            occurrence=occurrence,
        )
        if call.status != "PROVIDER_COMPLETED":
            raise ValueError("REWRITE_PROVIDER_NOT_COMPLETED")
        body = loads_strict_json(call.content)
        if (
            type(body) is not dict
            or set(body) != {"diagnosis", "strategy", "mutation", "files"}
            or type(body["diagnosis"]) is not str
            or len(body["diagnosis"].strip()) < 8
        ):
            raise ValueError("REWRITE_DIAGNOSIS_REQUIRED")
        if type(body["files"]) is not dict:
            raise ValueError("REWRITE_FILES_REQUIRED")
        candidate = HarnessCandidateV1(
            incumbent.source,
            incumbent.candidate_id,
            tuple(sorted(body["files"].items())),
            body["strategy"],
            body["mutation"],
        )
        self.store.retain(candidate)
        self.store.record(
            occurrence + "/proposal",
            {
                "candidate": candidate.candidate_id,
                "model_evidence": call.evidence,
                "diagnosis": body["diagnosis"],
            },
        )
        return candidate

